import javax.swing.*; import java.awt.*;
public class SchoolManagementSwingDemo { public static void main(String[] args){SwingUtilities.invokeLater(()->{JFrame frame=new JFrame("School Management System");frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);JPanel panel=new JPanel(new GridLayout(0,1,8,8));panel.add(new JLabel("School Management System"));JTextField studentId=new JTextField();studentId.setBorder(BorderFactory.createTitledBorder("Student ID"));panel.add(studentId);JTextField studentName=new JTextField();studentName.setBorder(BorderFactory.createTitledBorder("Student name"));panel.add(studentName);JButton register=new JButton("Preview registration");register.addActionListener(e->JOptionPane.showMessageDialog(frame,"Student: "+studentId.getText()+" - "+studentName.getText()));panel.add(register);frame.add(panel);frame.pack();frame.setSize(380,260);frame.setLocationRelativeTo(null);frame.setVisible(true);});} }
